/* Extends the existing authenticated editor. All writes keep Supabase Auth/RLS. */
const catalogAPI=window.VisaCatalog;
let catalogDraft=[],calendarDraft=[],catalogFiles=new Map(),catalogDirty=false;
const originalRenderEditor=renderEditor;
const adminForm=document.querySelector('#editor-form');
// Multipage navigation replaces the old single-page section ordering.
document.querySelector('[data-tab="layout"]').hidden=true;
document.querySelector('[data-panel="layout"]').hidden=true;
const catalogPanel=document.querySelector('[data-panel="tours"]');
catalogPanel.querySelector('.panel-head').innerHTML='<div><h2>Путешествия и маршруты</h2></div><p>Создавайте поездки, редактируйте программу и фотографии. Изменения появятся на сайте после сохранения.</p>';
const addTourButton=document.createElement('button');addTourButton.type='button';addTourButton.textContent='Добавить путешествие';addTourButton.className='add-catalog-item';catalogPanel.querySelector('.panel-head').appendChild(addTourButton);
const calendarPanel=document.createElement('section');calendarPanel.className='panel';calendarPanel.dataset.panel='calendar';calendarPanel.innerHTML='<div class="panel-head"><div><h2>Календарь поездок</h2></div><p>У одного маршрута может быть несколько заездов. Укажите даты, статус и количество мест для каждого.</p><button type="button" id="add-departure">Добавить заезд</button></div><div id="departure-fields"></div>';
adminForm.insertBefore(calendarPanel,document.querySelector('.save-bar'));
const calendarTab=document.createElement('button');calendarTab.type='button';calendarTab.className='tab';calendarTab.dataset.tab='calendar';calendarTab.textContent='Календарь';document.querySelector('.dashboard nav').appendChild(calendarTab);
calendarTab.setAttribute('role','tab');calendarTab.setAttribute('aria-selected','false');
calendarTab.onclick=()=>activateAdminTab(calendarTab);
function markCatalogDirty(){catalogDirty=true;document.querySelector('#save-status').textContent='Есть несохранённые изменения.'}
adminForm.addEventListener('input',markCatalogDirty);
window.addEventListener('beforeunload',event=>{if(catalogDirty){event.preventDefault();event.returnValue=''}});
renderEditor=function(){originalRenderEditor();catalogDraft=catalogAPI.tours(activeConfig);calendarDraft=catalogAPI.calendar(activeConfig,catalogDraft);catalogFiles.clear();catalogDirty=false;renderCatalogEditor();renderDepartureEditor()};
function field(label,key,value,type='text',wide=false){return `<label class="field ${wide?'wide':''}"><span>${label}</span><input data-key="${key}" type="${type==='url'?'text':type}" ${type==='url'?'inputmode="url"':''} value="${escapeAttr(value)}"></label>`}
function textArea(label,key,value){return `<label class="field wide"><span>${label}</span><textarea data-key="${key}" rows="4">${escapeAttr(value)}</textarea></label>`}
function renderCatalogEditor(){
 const root=document.querySelector('#tour-fields');
 root.innerHTML=catalogDraft.length?catalogDraft.map((t,index)=>`<details class="catalog-tour" data-index="${index}" ${index===catalogDraft.length-1?'open':''}><summary><span>${escapeAttr(t.title||'Новое путешествие')}</span><span class="publication-state">${t.published?'На сайте':'Черновик'}</span></summary><div class="catalog-tour-body"><div class="catalog-actions"><a href="/trip.html?id=${encodeURIComponent(t.id)}" target="_blank" rel="noopener">Открыть страницу ↗</a><button type="button" data-action="up" data-index="${index}" ${index===0?'disabled':''}>Выше</button><button type="button" data-action="down" data-index="${index}" ${index===catalogDraft.length-1?'disabled':''}>Ниже</button><button type="button" data-action="duplicate" data-index="${index}">Копировать</button><button type="button" class="secondary" data-action="archive" data-index="${index}">${t.published?'Снять с публикации':'Опубликовать'}</button><button type="button" class="secondary" data-action="delete" data-index="${index}">Удалить</button></div><div class="tour-inputs">${field('Название','title',t.title)}<label class="field"><span>Формат</span><select data-key="category">${[['group','Групповое'],['expedition','Экспедиция'],['private','Индивидуальное']].map(([v,l])=>`<option value="${v}" ${t.category===v?'selected':''}>${l}</option>`).join('')}</select></label>${field('Города маршрута','route',t.route,'text',true)}${field('Даты на карточке','dates',t.dates)}${field('Продолжительность','days',t.days)}${field('Стоимость','price',t.price)}${field('Количество мест','places',t.places)}${field('Статус','status',t.status)}${field('Ссылка на обложку','image',t.image,'url')}${textArea('Описание путешествия','desc',t.desc)}<label class="field wide"><span>Загрузить обложку · JPG, PNG или WebP до 5 МБ</span><input type="file" accept="image/jpeg,image/png,image/webp" data-cover="${index}"></label><img class="catalog-preview" src="${escapeAttr(catalogAPI.url(t.image))}" alt="Обложка путешествия"><div class="wide"><h3>Программа по дням</h3><p>Название, описание и фотография каждого дня редактируются отдельно.</p><div class="day-editor-list">${t.program.map((day,i)=>{const d=typeof day==='string'?{title:day}:day;return `<div class="cms-day" data-day="${i}">${field('День '+(i+1)+' · название','dayTitle',d.title)}${textArea('Подробности дня','dayDescription',d.description||'')}${field('Фотография дня · URL','dayImage',d.image||'','url')}${d.image?`<img class="catalog-preview" src="${escapeAttr(String(d.image).startsWith('blob:')?d.image:catalogAPI.url(d.image))}" alt="Фото дня ${i+1}" loading="lazy">`:''}<label class="field"><span>Загрузить фото дня</span><input type="file" accept="image/jpeg,image/png,image/webp" data-day-upload="${i}"></label><button type="button" data-remove-day="${i}">Убрать день</button></div>`}).join('')}</div><button type="button" data-add-day="${index}">Добавить день</button></div>${textArea('Включено · каждый пункт с новой строки','included',t.included.join('\n'))}${textArea('Оплачивается отдельно · каждый пункт с новой строки','excluded',t.excluded.join('\n'))}<div class="wide"><h3>Фотографии путешествия</h3><p>Порядок фотографий соответствует порядку ссылок. Можно вставить URL или загрузить несколько файлов.</p>${textArea('URL фотографий · каждый с новой строки','gallery',t.gallery.map(p=>typeof p==='string'?p:p.url).join('\n'))}<label class="field"><span>Загрузить фотографии · до 5 МБ каждая</span><input type="file" multiple accept="image/jpeg,image/png,image/webp" data-gallery="${index}"></label><div class="cms-gallery">${t.gallery.map(p=>`<img src="${escapeAttr(catalogAPI.url(typeof p==='string'?p:p.url))}" alt="Фото маршрута" loading="lazy">`).join('')}</div></div></div></div></details>`).join(''):'<p class="empty-state">Путешествий пока нет. Добавьте первый маршрут.</p>';
 root.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{collectCatalog();const i=Number(b.dataset.index),action=b.dataset.action;if(action==='delete'){if(!confirm('Удалить путешествие и его заезды из каталога? Изменение применится после сохранения.'))return;calendarDraft=calendarDraft.filter(d=>d.tourId!==catalogDraft[i].id);catalogDraft.splice(i,1)}if(action==='archive')catalogDraft[i].published=!catalogDraft[i].published;if(action==='duplicate'){const copy=catalogAPI.clone(catalogDraft[i]);copy.id=crypto.randomUUID();copy.title+=' — копия';copy.published=false;catalogDraft.push(copy)}if(action==='up'||action==='down'){const j=i+(action==='up'?-1:1);[catalogDraft[i],catalogDraft[j]]=[catalogDraft[j],catalogDraft[i]]}markCatalogDirty();renderCatalogEditor();renderDepartureEditor()});
 root.querySelectorAll('[data-add-day]').forEach(b=>b.onclick=()=>{collectCatalog();catalogDraft[Number(b.dataset.addDay)].program.push({title:'Новый день',description:'',image:''});markCatalogDirty();renderCatalogEditor()});
 root.querySelectorAll('[data-remove-day]').forEach(b=>b.onclick=()=>{collectCatalog();catalogDraft[Number(b.closest('[data-index]').dataset.index)].program.splice(Number(b.dataset.removeDay),1);markCatalogDirty();renderCatalogEditor()});
 root.querySelectorAll('[data-cover],[data-gallery],[data-day-upload]').forEach(input=>input.onchange=()=>queueCatalogFiles(input));
}
function collectCatalog(){document.querySelectorAll('.catalog-tour').forEach(el=>{const t=catalogDraft[Number(el.dataset.index)];el.querySelectorAll('[data-key]').forEach(input=>{const key=input.dataset.key;if(key.startsWith('day'))return;if(['included','excluded','gallery'].includes(key))t[key]=input.value.split('\n').map(s=>s.trim()).filter(Boolean);else t[key]=input.value});t.program=[...el.querySelectorAll('[data-day]')].map(day=>({title:day.querySelector('[data-key="dayTitle"]').value,description:day.querySelector('[data-key="dayDescription"]').value,image:day.querySelector('[data-key="dayImage"]').value}))});collectDepartures()}
async function queueCatalogFiles(input){
 const files=[...input.files];if(files.some(f=>!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5000000)){alert('Выберите JPG, PNG или WebP размером до 5 МБ.');input.value='';return}
 collectCatalog();const t=catalogDraft[Number(input.closest('.catalog-tour').dataset.index)];
 for(const file of files){const preview=URL.createObjectURL(file);catalogFiles.set(preview,{file,tourId:t.id});if(input.hasAttribute('data-cover'))t.image=preview;else if(input.hasAttribute('data-day-upload'))t.program[Number(input.dataset.dayUpload)].image=preview;else t.gallery.push(preview)}markCatalogDirty();renderCatalogEditor();
}
function renderDepartureEditor(){document.querySelector('#departure-fields').innerHTML=calendarDraft.length?calendarDraft.map((d,i)=>`<article class="departure-editor" data-departure="${i}"><div class="tour-inputs"><label class="field"><span>Путешествие</span><select data-departure-key="tourId">${catalogDraft.map(t=>`<option value="${escapeAttr(t.id)}" ${d.tourId===t.id?'selected':''}>${escapeAttr(t.title)}</option>`).join('')}</select></label>${['start','end','label','status','places'].map(key=>`<label class="field"><span>${({start:'Дата начала',end:'Дата окончания',label:'Подпись даты (если точная дата неизвестна)',status:'Статус набора',places:'Оставшиеся места'})[key]}</span><input data-departure-key="${key}" type="${key==='start'||key==='end'?'date':'text'}" value="${escapeAttr(d[key])}"></label>`).join('')}<label class="field"><span>Публикация</span><select data-departure-key="published"><option value="true" ${d.published!==false?'selected':''}>Показать в календаре</option><option value="false" ${d.published===false?'selected':''}>Черновик</option></select></label></div><button type="button" data-remove-departure="${i}" class="secondary">Удалить заезд</button></article>`).join(''):'<p class="empty-state">Заездов пока нет. Добавьте дату для любого маршрута.</p>';document.querySelectorAll('[data-remove-departure]').forEach(b=>b.onclick=()=>{collectDepartures();calendarDraft.splice(Number(b.dataset.removeDeparture),1);markCatalogDirty();renderDepartureEditor()})}
function collectDepartures(){document.querySelectorAll('[data-departure]').forEach(el=>{const d=calendarDraft[Number(el.dataset.departure)];el.querySelectorAll('[data-departure-key]').forEach(input=>d[input.dataset.departureKey]=input.dataset.departureKey==='published'?input.value==='true':input.value)})}
addTourButton.onclick=()=>{collectCatalog();catalogDraft.push({id:crypto.randomUUID(),title:'Новое путешествие',category:'group',published:false,route:'',dates:'',days:'',price:'',places:'',status:'Скоро анонс',image:'/assets/media/tour-private-asia.jpg',desc:'',program:[],gallery:[],included:[],excluded:[]});markCatalogDirty();renderCatalogEditor();renderDepartureEditor()};
document.querySelector('#add-departure').onclick=()=>{collectCatalog();if(!catalogDraft.length){alert('Сначала добавьте путешествие.');return}calendarDraft.push({id:crypto.randomUUID(),tourId:catalogDraft[0].id,start:'',end:'',label:'',status:'Открыт набор',places:'',published:false});markCatalogDirty();renderDepartureEditor()};
adminForm.onsubmit=async event=>{
 event.preventDefault();collectCatalog();const status=document.querySelector('#save-status'),submit=adminForm.querySelector('[type="submit"]');
 const invalid=catalogDraft.find(t=>!t.title.trim()||(t.published&&(!t.route.trim()||!t.desc.trim()||!t.program.length||t.program.some(day=>!String(typeof day==='string'?day:day.title||'').trim())||!t.included.length||!t.excluded.length)));if(invalid){status.textContent=`Маршрут «${invalid.title||'Без названия'}» не готов к публикации. Добавьте описание, программу, а также списки «Включено» и «Оплачивается отдельно».`;return}
 if(calendarDraft.some(d=>!catalogDraft.some(t=>t.id===d.tourId)||(d.published&&!d.start&&!d.label.trim())||(d.start&&d.end&&d.end<d.start))){status.textContent='Проверьте календарь: укажите маршрут и даты; окончание должно быть не раньше начала.';return}
 if(catalogDraft.some(t=>[t.image,...t.gallery,...t.program.map(d=>d.image)].some(v=>v&&!String(v).startsWith('blob:')&&!catalogAPI.url(v)))){status.textContent='Проверьте ссылки на фотографии: используйте HTTP или HTTPS.';return}
 submit.disabled=true;adminForm.inert=true;status.textContent='Загружаем файлы и сохраняем…';
 try{
  const draft=catalogAPI.clone(catalogDraft),fd=new FormData(adminForm),content={...activeConfig.content},media={...defaultMedia,...activeConfig.media};
  for(const [key,value]of fd){if(key.startsWith('content.'))content[key.slice(8)]=String(value);if(key.startsWith('media.'))media[key.slice(6)]=String(value)}
  for(const [preview,{file,tourId}]of catalogFiles){const t=draft.find(t=>t.id===tourId);if(!t)continue;const used=t.image===preview||t.gallery.includes(preview)||t.program.some(d=>d.image===preview);if(!used)continue;const uploaded=await uploadFile(file,'tours/'+tourId);if(t.image===preview)t.image=uploaded;t.gallery=t.gallery.map(p=>p===preview?uploaded:p);t.program=t.program.map(d=>({...d,image:d.image===preview?uploaded:d.image}))}
  for(const [key,file]of Object.entries(mediaUploads))media[key]=await uploadFile(file,'media/'+key);
  const faqFields=[...adminForm.querySelectorAll('[name^="faq."]')];const faqs=[];for(let i=0;i<faqFields.length/2;i++)faqs.push([String(fd.get(`faq.${i}.q`)||''),String(fd.get(`faq.${i}.a`)||'')]);
  content.catalogVersion='2';content.calendarData=JSON.stringify(calendarDraft);
  const {data:{user}}=await db.auth.getUser();if(!user)throw new Error('Сессия истекла. Войдите снова.');
  const {error}=await db.from('site_config').upsert({id:'main',content,media,tours:draft,faqs,section_order:order,updated_at:new Date().toISOString(),updated_by:user.id});if(error)throw error;
  activeConfig={content,media,tours:draft,faqs,sectionOrder:order};catalogDraft=draft;catalogFiles.forEach((_,preview)=>URL.revokeObjectURL(preview));catalogFiles.clear();mediaUploads={};catalogDirty=false;renderCatalogEditor();renderDepartureEditor();status.textContent='Сохранено. Каталог, страницы поездок и календарь обновлены.';
 }catch(error){status.textContent='Не удалось сохранить: '+error.message+'. Изменения остались в редакторе.'}finally{submit.disabled=false;adminForm.inert=false}
};
// This replaces the destructive reset with a confirmation that explains its actual scope.
document.querySelector('#reset-dialog p').textContent='Сброс удалит сохранённые тексты, маршруты, фотографии и календарь из настроек сайта. Загруженные файлы останутся в хранилище. Используйте только для возврата к исходному каталогу.';
